// PATCH v1.3.2: загружаем ДЕРЕВО ЦЕЛИКОМ (все гипотезы и задания)
// PATCH v1.3.3: нормализация — каждую гипотезу ставим вместе с её
// заданиями (иначе addTask, ищущий детей подряд, мог прицепить
// задание не туда); пересчёт бейджа; рендер через __renderHypTree.
var _hd = (task && Array.isArray(task.hypotheses)) ? JSON.parse(JSON.stringify(task.hypotheses)) : [];
var _hm = _hd.filter(function(x){ return x.kind === 'hypothesis'; });
var _nm = [];
for (var _hi = 0; _hi < _hm.length; _hi++) {
    _nm.push(_hm[_hi]);
    _hd.forEach(function(x){ if (x.kind === 'task' && x.parent === _hm[_hi].id) _nm.push(x); });
}
_hd.forEach(function(x){ if (_nm.indexOf(x) === -1) _nm.push(x); });
window.__trkHypDraft = _nm;
var _hb = document.getElementById('hypCountBadge');
if (_hb) _hb.textContent = _hm.length + ' гип., ' + _nm.filter(function(x){return x.kind==='task';}).length + ' зад.';
if (typeof window.__renderHypTree === 'function') window.__renderHypTree();
else if (typeof renderHypTree === 'function') renderHypTree();

.hyp-card { width: 100%; box-sizing: border-box; display: flex; flex-direction: column;
  border: 1px solid var(--border, #3a3f4b); border-radius: 10px; padding: 10px 12px;
  background: rgba(255,255,255,0.03); }
.hyp-tree { width: 100%; display: flex; flex-direction: column; gap: 8px; }
.hyp-fields { display: flex; flex-direction: column; gap: 6px; width: 100%; }
.hyp-fld { box-sizing: border-box; max-width: 100%; }
#taskHypothesesGroup { grid-column: 1 / -1; width: 100%; }
